#!/usr/bin/env python3
"""FS3 v169 - Shivan cycle, block B part 1: missions 67 to 70.

    TAG       new secondary TAG-C (missile, from mission 67): a tagged ship
              is held by our beams for 12 s even in the nebula, and a
              tagged gas miner or freighter counts for the heavy beams.
              Orange brackets mark it.
    Setekh    AWACS that jams the Shivans: no reinforcements, no calls from
              capital ships while she lives. They answer with subspace
              bombs out of vortices at least 350 points from her, mostly
              at the edge of the field.
    Timer     a mission clock ('timer', 'zeit', 'timerStopp'), shown at the
              top right; while it runs the wave does not end.
    Nebula    enemy capital guns see our ships only within 460 points in
              the gas (as they always did the player).
    M67       The Gas Miners: four Rahu, TAG them for the Orion's beams.
    M68       Radio Silence: protect the Setekh against subspace bombs.
    M69       The Shadow: the Lucifer (shield, untouchable) while the
              Hecate charges her jump drive for 80 s.
    M70       The Iceni: she holds until our transport has her crew off.
    Missions  new: giveSec, ssBombs, noKill on allies, noFire, still on
              freighters, 'sd' units (super destroyers by name).

Needs v168. Edits src/30_waves.js, src/40_world.js, src/50_combat.js,
src/60_effects.js and src/70_ui.js in place, and writes the updated
fieldsim.js and swtest.js. Run assemble.py afterwards.
"""
import base64
import os
import sys

if "function portalPoint" not in open("src/30_waves.js", encoding="utf-8").read():
    sys.exit("Abbruch: erst v168 einspielen.")
if "TAG_TIME" in open("src/50_combat.js", encoding="utf-8").read():
    sys.exit("Abbruch: v169 ist schon eingespielt.")

F = {}
def load(p):
    if p not in F: F[p] = open(p, encoding="utf-8").read()
def rep(p, old, new, count=1):
    load(p)
    n = F[p].count(old)
    if n != count:
        sys.exit("Abbruch (%s): Suchtext %d-mal gefunden, erwartet %d.\n%s" % (p, n, count, old[:200]))
    F[p] = F[p].replace(old, new)

